import { useMemo, useState } from "react";
import styles from "./UserMaster.module.css";
import { useUserMaster } from "./useUserMaster";

/**
 * Functional responsibility:
 * - Render reusable User Master UI (list + add/edit form) driven by useUserMaster hook.
 * Inputs:
 * - apiEndpoint: string endpoint for CRUD requests.
 * - title/subtitle: display labels.
 * - fieldMap: user field keys for id/name/email/role.
 * - callbacks: onSuccess/onError/onUsersChange/onCreate/onUpdate/onDelete.
 * Output:
 * - Reusable component suitable for host apps or package export.
 * Failure behavior:
 * - Renders strError message and keeps UI usable for retries.
 */
export default function UserMaster({
  apiEndpoint = "/api/users",
  title = "User Master",
  subtitle = "Manage user records from a reusable module",
  fieldMap,
  onSuccess,
  onError,
  onUsersChange,
  onCreate,
  onUpdate,
  onDelete,
  fetchOptions,
  transformResponse,
  className = ""
}) {
  const dicFieldMap = useMemo(
    () => ({
      id: fieldMap?.id || "id",
      name: fieldMap?.name || "name",
      email: fieldMap?.email || "email",
      role: fieldMap?.role || "role"
    }),
    [fieldMap]
  );

  const {
    lstUsers,
    intIsLoading,
    intIsSubmitting,
    strError,
    createUser,
    updateUser,
    deleteUser,
    loadUsers
  } = useUserMaster({
    apiEndpoint,
    fetchOptions,
    transformResponse,
    onSuccess,
    onError,
    onUsersChange,
    onCreate,
    onUpdate,
    onDelete
  });

  const [strEditingId, setStrEditingId] = useState("");
  const [dicForm, setDicForm] = useState({
    name: "",
    email: "",
    role: ""
  });

  const resetForm = () => {
    setStrEditingId("");
    setDicForm({ name: "", email: "", role: "" });
  };

  const handleChange = (strField, strValue) => {
    setDicForm((dicPrev) => ({ ...dicPrev, [strField]: strValue }));
  };

  const handleEdit = (dicUser) => {
    setStrEditingId(String(dicUser[dicFieldMap.id] ?? ""));
    setDicForm({
      name: String(dicUser[dicFieldMap.name] ?? ""),
      email: String(dicUser[dicFieldMap.email] ?? ""),
      role: String(dicUser[dicFieldMap.role] ?? "")
    });
  };

  const handleSubmit = async (event) => {
    event.preventDefault();

    const dicPayload = {
      [dicFieldMap.name]: dicForm.name,
      [dicFieldMap.email]: dicForm.email,
      [dicFieldMap.role]: dicForm.role
    };

    if (strEditingId) {
      dicPayload[dicFieldMap.id] = strEditingId;
      await updateUser(dicPayload);
      resetForm();
      return;
    }

    await createUser(dicPayload);
    resetForm();
  };

  const handleDelete = async (strUserId) => {
    await deleteUser(strUserId);
    if (strEditingId === strUserId) {
      resetForm();
    }
  };

  return (
    <section className={`${styles.wrapper} ${className}`.trim()}>
      <header className={styles.header}>
        <div>
          <h2 className={styles.title}>{title}</h2>
          <p className={styles.subtitle}>{subtitle}</p>
        </div>
        <button type="button" className={`${styles.button} ${styles.ghost}`} onClick={loadUsers} disabled={intIsLoading === 1}>
          {intIsLoading === 1 ? "Refreshing..." : "Refresh"}
        </button>
      </header>

      <div className={styles.card}>
        <div className={styles.content}>
          <form className={styles.form} onSubmit={handleSubmit}>
            <label className={styles.field}>
              <span className={styles.label}>Name</span>
              <input
                className={styles.input}
                value={dicForm.name}
                onChange={(event) => handleChange("name", event.target.value)}
                required
              />
            </label>
            <label className={styles.field}>
              <span className={styles.label}>Email</span>
              <input
                className={styles.input}
                type="email"
                value={dicForm.email}
                onChange={(event) => handleChange("email", event.target.value)}
                required
              />
            </label>
            <label className={styles.field}>
              <span className={styles.label}>Role</span>
              <input
                className={styles.input}
                value={dicForm.role}
                onChange={(event) => handleChange("role", event.target.value)}
                required
              />
            </label>
            <div className={styles.actions}>
              <button type="submit" className={`${styles.button} ${styles.primary}`} disabled={intIsSubmitting === 1}>
                {intIsSubmitting === 1 ? "Saving..." : strEditingId ? "Update User" : "Create User"}
              </button>
              {strEditingId ? (
                <button type="button" className={`${styles.button} ${styles.ghost}`} onClick={resetForm}>
                  Cancel Edit
                </button>
              ) : null}
            </div>
          </form>

          {strError ? <p className={styles.error}>{strError}</p> : null}
        </div>
      </div>

      <div className={styles.card}>
        <div className={styles.content}>
          {lstUsers.length === 0 ? (
            <p className={styles.empty}>{intIsLoading === 1 ? "Loading users..." : "No users found."}</p>
          ) : (
            <table className={styles.grid}>
              <thead>
                <tr>
                  <th>Name</th>
                  <th>Email</th>
                  <th>Role</th>
                  <th>Actions</th>
                </tr>
              </thead>
              <tbody>
                {lstUsers.map((dicUser) => {
                  const strUserId = String(dicUser[dicFieldMap.id]);
                  return (
                    <tr key={strUserId}>
                      <td>{String(dicUser[dicFieldMap.name] ?? "-")}</td>
                      <td>{String(dicUser[dicFieldMap.email] ?? "-")}</td>
                      <td>{String(dicUser[dicFieldMap.role] ?? "-")}</td>
                      <td>
                        <div className={styles.actions}>
                          <button
                            type="button"
                            className={`${styles.button} ${styles.ghost}`}
                            onClick={() => handleEdit(dicUser)}
                          >
                            Edit
                          </button>
                          <button
                            type="button"
                            className={`${styles.button} ${styles.ghost}`}
                            onClick={() => handleDelete(strUserId)}
                          >
                            Delete
                          </button>
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          )}
        </div>
      </div>
    </section>
  );
}
