import { useCallback, useEffect, useMemo, useState } from "react";

/**
 * Functional responsibility:
 * - Encapsulate User Master business logic and API communication.
 * Inputs:
 * - dicOptions.apiEndpoint: API base URL for user operations.
 * - dicOptions.fetchOptions: optional headers/options for fetch calls.
 * - dicOptions.transformResponse: optional response mapper.
 * - dicOptions callbacks: onSuccess, onError, onUsersChange, onCreate, onUpdate, onDelete.
 * Output:
 * - Returns state + command handlers for CRUD lifecycle.
 * Failure behavior:
 * - Captures network/HTTP errors, sets strError, and triggers onError callback.
 */
export function useUserMaster(dicOptions = {}) {
  const {
    apiEndpoint = "/api/users",
    fetchOptions = {},
    transformResponse,
    onSuccess,
    onError,
    onUsersChange,
    onCreate,
    onUpdate,
    onDelete
  } = dicOptions;

  const [lstUsers, setLstUsers] = useState([]);
  const [intIsLoading, setIntIsLoading] = useState(0);
  const [intIsSubmitting, setIntIsSubmitting] = useState(0);
  const [strError, setStrError] = useState("");

  const requestJson = useCallback(
    async (strUrl, dicInit = {}) => {
      const dicMergedInit = {
        ...fetchOptions,
        ...dicInit,
        headers: {
          "Content-Type": "application/json",
          ...(fetchOptions.headers || {}),
          ...(dicInit.headers || {})
        }
      };

      const dicResponse = await fetch(strUrl, dicMergedInit);
      const strRawBody = await dicResponse.text();
      const dicBody = strRawBody ? JSON.parse(strRawBody) : null;

      if (!dicResponse.ok) {
        const strMessage = dicBody?.message || `Request failed (${dicResponse.status})`;
        throw new Error(strMessage);
      }

      return dicBody;
    },
    [fetchOptions]
  );

  const normalizeUsers = useCallback(
    (dicPayload) => {
      if (typeof transformResponse === "function") {
        return transformResponse(dicPayload);
      }
      if (Array.isArray(dicPayload)) {
        return dicPayload;
      }
      if (Array.isArray(dicPayload?.data)) {
        return dicPayload.data;
      }
      if (Array.isArray(dicPayload?.users)) {
        return dicPayload.users;
      }
      return [];
    },
    [transformResponse]
  );

  const loadUsers = useCallback(async () => {
    setIntIsLoading(1);
    setStrError("");

    try {
      const dicPayload = await requestJson(apiEndpoint, { method: "GET" });
      const lstNormalizedUsers = normalizeUsers(dicPayload);
      setLstUsers(lstNormalizedUsers);
      if (typeof onUsersChange === "function") {
        onUsersChange(lstNormalizedUsers);
      }
      if (typeof onSuccess === "function") {
        onSuccess({ type: "load", data: lstNormalizedUsers });
      }
    } catch (dicError) {
      const strMessage = dicError instanceof Error ? dicError.message : "Failed to load users";
      setStrError(strMessage);
      if (typeof onError === "function") {
        onError({ type: "load", error: dicError });
      }
    } finally {
      setIntIsLoading(0);
    }
  }, [apiEndpoint, normalizeUsers, onError, onSuccess, onUsersChange, requestJson]);

  useEffect(() => {
    loadUsers();
  }, [loadUsers]);

  const upsertUser = useCallback(
    async (dicUserPayload, strMode = "create") => {
      setIntIsSubmitting(1);
      setStrError("");

      try {
        const intIsUpdateMode = strMode === "update" ? 1 : 0;
        const strId = dicUserPayload?.id ?? "";
        const strUrl = intIsUpdateMode === 1 ? `${apiEndpoint}/${strId}` : apiEndpoint;

        const dicSavedUser = await requestJson(strUrl, {
          method: intIsUpdateMode === 1 ? "PUT" : "POST",
          body: JSON.stringify(dicUserPayload)
        });

        if (intIsUpdateMode === 1) {
          if (typeof onUpdate === "function") {
            onUpdate(dicSavedUser);
          }
        } else if (typeof onCreate === "function") {
          onCreate(dicSavedUser);
        }

        if (typeof onSuccess === "function") {
          onSuccess({ type: strMode, data: dicSavedUser });
        }

        await loadUsers();
        return { intIsSuccess: 1, data: dicSavedUser };
      } catch (dicError) {
        const strMessage = dicError instanceof Error ? dicError.message : "Failed to save user";
        setStrError(strMessage);
        if (typeof onError === "function") {
          onError({ type: strMode, error: dicError });
        }
        return { intIsSuccess: 0, error: dicError };
      } finally {
        setIntIsSubmitting(0);
      }
    },
    [apiEndpoint, loadUsers, onCreate, onError, onSuccess, onUpdate, requestJson]
  );

  const deleteUser = useCallback(
    async (strUserId) => {
      setIntIsSubmitting(1);
      setStrError("");

      try {
        await requestJson(`${apiEndpoint}/${strUserId}`, { method: "DELETE" });

        if (typeof onDelete === "function") {
          onDelete(strUserId);
        }

        if (typeof onSuccess === "function") {
          onSuccess({ type: "delete", data: { id: strUserId } });
        }

        await loadUsers();
        return { intIsSuccess: 1 };
      } catch (dicError) {
        const strMessage = dicError instanceof Error ? dicError.message : "Failed to delete user";
        setStrError(strMessage);
        if (typeof onError === "function") {
          onError({ type: "delete", error: dicError });
        }
        return { intIsSuccess: 0, error: dicError };
      } finally {
        setIntIsSubmitting(0);
      }
    },
    [apiEndpoint, loadUsers, onDelete, onError, onSuccess, requestJson]
  );

  const dicState = useMemo(
    () => ({
      lstUsers,
      intIsLoading,
      intIsSubmitting,
      strError
    }),
    [intIsLoading, intIsSubmitting, lstUsers, strError]
  );

  return {
    ...dicState,
    loadUsers,
    createUser: (dicUserPayload) => upsertUser(dicUserPayload, "create"),
    updateUser: (dicUserPayload) => upsertUser(dicUserPayload, "update"),
    deleteUser
  };
}
